import type { Journey, JourneyStep } from "#lib/journey.ts";
import data from "./journey.json";

/** Generated by `scripts/import-polarsteps.ts`; steps are sorted by time. */
export const journey = data as unknown as Journey;

export function getStep(slug: string): { step: JourneyStep; index: number } | undefined {
	const index = journey.steps.findIndex((step) => step.slug === slug);
	return index === -1 ? undefined : { step: journey.steps[index], index };
}

